changeSet.sql:
ALTER TABLE membership ADD COLUMN role_source varchar(16) DEFAULT 'PROVIDER' NOT NULL;
UPDATE membership SET role_source = 'PERSON' WHERE role = 'OWNER';
ALTER TABLE membership ADD CONSTRAINT ck_membership_role_source CHECK (role_source IN ('PROVIDER', 'PERSON'));
ALTER TABLE membership ADD CONSTRAINT ck_membership_owner_role_source CHECK (role <> 'OWNER' OR role_source = 'PERSON');

changeSet.rollback:
ALTER TABLE membership DROP CONSTRAINT ck_membership_owner_role_source;
ALTER TABLE membership DROP CONSTRAINT ck_membership_role_source;
ALTER TABLE membership DROP COLUMN role_source;
